package com.inventra.backend.controller;
import com.inventra.backend.dto.*; import com.inventra.backend.service.ProductService; import jakarta.validation.Valid; import org.springframework.data.domain.Pageable; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductService s;public ProductController(ProductService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ProductResponse create(@Valid @RequestBody ProductRequest r){return s.createProduct(r);}@GetMapping public List<ProductResponse> all(){return s.getAllProducts();}@GetMapping("/page") public ProductPageResponse page(Pageable p){return s.getProducts(p);}@GetMapping("/low-stock") public List<ProductResponse> low(){return s.getLowStockProducts();}@GetMapping("/{id}") public ProductResponse get(@PathVariable String id){return s.getProductById(id);}@PutMapping("/{id}") public ProductResponse update(@PathVariable String id,@Valid @RequestBody ProductRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable String id){s.delete(id);}}
